import{_ as r,y as s,a as n,o as i,a2 as e,D as a}from"./chunks/framework.DCcmcJcL.js";const m=JSON.parse('{"title":"Shipping Methods","description":"","frontmatter":{},"headers":[],"relativePath":"shipping-method/shipping-methods.md","filePath":"shipping-method/shipping-methods.md","lastUpdated":1789441803000}'),h={name:"shipping-method/shipping-methods.md"};function p(g,t,d,c,l,u){const o=s("ImagePopup");return i(),n("div",null,[t[0]||(t[0]=e('<h1 id="shipping-methods" tabindex="-1">Shipping Methods <a class="header-anchor" href="#shipping-methods" aria-label="Permalink to &quot;Shipping Methods&quot;">​</a></h1><p>Bagisto comes with two shipping methods, <strong>Free Shipping</strong> and <strong>Flat Rate Shipping</strong>. At checkout, shoppers choose from the methods that are switched on. Both are switched on in a new store.</p><h2 id="offer-a-shipping-method" tabindex="-1">Offer a shipping method <a class="header-anchor" href="#offer-a-shipping-method" aria-label="Permalink to &quot;Offer a shipping method&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Sales &gt;&gt; Shipping Methods</strong>.</li><li>If your store has more than one channel or language, choose them at the top of the screen.</li><li>In the method&#39;s section, switch <strong>Status</strong> on. <strong>Title</strong>, and for Flat Rate Shipping <strong>Rate</strong>, appear.</li><li>Enter the <strong>Title</strong> shoppers see at checkout.</li><li>Optionally, enter a <strong>Description</strong>.</li><li>For <strong>Flat Rate Shipping</strong>, enter the <strong>Rate</strong>.</li><li>For <strong>Flat Rate Shipping</strong>, choose the <strong>Type</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',4)),a(o,{src:"/images/configure/shipping-methods-settings.png",alt:"Shipping Methods screen with Free Shipping and Flat Rate Shipping switched on"}),t[1]||(t[1]=e('<p>To stop offering a method, switch its <strong>Status</strong> off and save. At least one shipping method has to stay on: saving with both switched off shows <strong>Enable at least one shipping method.</strong> <strong>Title</strong> and <strong>Description</strong> are per channel and per language; the other settings are per channel.</p><p>At checkout, each method shows its title, its description and its price. So does the shipping estimate on the cart page, while <strong>Estimated Shipping</strong> is on under <a href="./../configure/checkout.html">Checkout</a>.</p><h2 id="free-shipping" tabindex="-1">Free shipping <a class="header-anchor" href="#free-shipping" aria-label="Permalink to &quot;Free shipping&quot;">​</a></h2><p>Free Shipping charges nothing for delivery.</p><p><strong>Title:</strong> The name of the method at checkout, such as <code>Free Shipping</code>. Required while <strong>Status</strong> is on.</p><p><strong>Description:</strong> A short line shown after the title.</p><p><strong>Status:</strong> Offers the method at checkout.</p><h2 id="flat-rate-shipping" tabindex="-1">Flat rate shipping <a class="header-anchor" href="#flat-rate-shipping" aria-label="Permalink to &quot;Flat rate shipping&quot;">​</a></h2><p>Flat Rate Shipping charges a fixed rate, either once per order or for each unit.</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Title</strong></td><td>The name of the method at checkout, such as <code>Flat Rate</code>. Required while <strong>Status</strong> is on.</td></tr><tr><td><strong>Description</strong></td><td>A short line shown after the title.</td></tr><tr><td><strong>Rate</strong></td><td>The amount charged, in your store&#39;s base currency. Shoppers see it converted to the currency they shop in. Required while <strong>Status</strong> is on.</td></tr><tr><td><strong>Type</strong></td><td><strong>Per Unit</strong> charges the rate for each unit of every shipped product in the cart, so three units cost three times the rate. Virtual, downloadable and booking products aren&#39;t counted. <strong>Per Order</strong> charges the rate once for the whole order.</td></tr><tr><td><strong>Status</strong></td><td>Offers the method at checkout.</td></tr></tbody></table><p>In a new store, Flat Rate Shipping charges a rate of <code>10</code> per unit.</p><p>The address orders are shipped from is set under <a href="./../configure/shipping.html">Shipping Settings</a>.</p>',12))])}const S=r(h,[["render",p]]);export{m as __pageData,S as default};
